-- NEXORIA Warrior Skill Expansion V1: new reserved IDs only.
-- Disable ENABLE_WARRIOR_SKILL_EXPANSION or data/warrior_skills.json enabled to retain original gameplay.
-- Run with collision preflight and backup; existing proto tables may be non-transactional.
SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS warrior_skill_choices (
 player_id INT UNSIGNED NOT NULL,
 tier TINYINT UNSIGNED NOT NULL,
 skill_id SMALLINT UNSIGNED NOT NULL,
 skill_level TINYINT UNSIGNED NOT NULL DEFAULT 1,
 spent_points TINYINT UNSIGNED NOT NULL DEFAULT 0,
 successful_reads SMALLINT UNSIGNED NOT NULL DEFAULT 0,
 next_read BIGINT UNSIGNED NOT NULL DEFAULT 0,
 PRIMARY KEY(player_id,tier),
 UNIQUE KEY warrior_one_choice_per_skill(player_id,skill_id),
 CONSTRAINT warrior_spent_points_valid CHECK(spent_points BETWEEN 0 AND 16),
 CONSTRAINT warrior_tier_valid CHECK(tier BETWEEN 0 AND 4),
 CONSTRAINT warrior_skill_valid CHECK(skill_id BETWEEN 180 AND 192),
 CONSTRAINT warrior_category_valid CHECK((tier=0 AND skill_id BETWEEN 180 AND 183) OR (tier BETWEEN 1 AND 3 AND skill_id BETWEEN 184 AND 189) OR (tier=4 AND skill_id BETWEEN 190 AND 192)),
 CONSTRAINT warrior_read_stage_valid CHECK(successful_reads=0 OR (skill_level BETWEEN 20 AND 29 AND successful_reads<skill_level-18)),
 CONSTRAINT warrior_skill_level_valid CHECK(skill_level BETWEEN 1 AND 40),
 CONSTRAINT warrior_read_count_valid CHECK(successful_reads BETWEEN 0 AND 10)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

START TRANSACTION;
COMMIT;
